"use client";
import { useRef, useMemo } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

// ─── Shared helpers ────────────────────────────────────────────────────────────

function GlowRing({
  z, radius, tube = 0.065, segments = 6, rotSpeed, color, opacity,
}: {
  z: number; radius: number; tube?: number; segments?: number;
  rotSpeed: number; color: string; opacity: number;
}) {
  const ref = useRef<THREE.Mesh>(null);
  useFrame(({ clock }) => {
    if (ref.current) ref.current.rotation.z = clock.elapsedTime * rotSpeed;
  });
  return (
    <mesh ref={ref} position={[0, 0, z]}>
      <torusGeometry args={[radius, tube, segments, 120]} />
      <meshStandardMaterial
        color={color} emissive={color} emissiveIntensity={2.8}
        transparent opacity={opacity} depthWrite={false}
        blending={THREE.AdditiveBlending}
      />
    </mesh>
  );
}

// ─── Vortex particles (whole tunnel) ──────────────────────────────────────────

function VortexParticles() {
  const COUNT = 3200;
  const ref = useRef<THREE.Points>(null);

  const { positions, colors } = useMemo(() => {
    const positions = new Float32Array(COUNT * 3);
    const colors = new Float32Array(COUNT * 3);
    const c0 = new THREE.Color("#ff8d2b");
    const c1 = new THREE.Color("#0546f2");
    const c2 = new THREE.Color("#0a1a5c");

    for (let i = 0; i < COUNT; i++) {
      const t = i / COUNT;
      const angle = t * Math.PI * 28 + Math.random() * 0.5;
      const r = 0.5 + Math.random() * 3.5;
      positions[i * 3]     = Math.cos(angle) * r;
      positions[i * 3 + 1] = Math.sin(angle) * r;
      positions[i * 3 + 2] = -t * 135;

      const c = t < 0.35
        ? c0.clone().lerp(c1, t / 0.35)
        : c1.clone().lerp(c2, (t - 0.35) / 0.65);
      colors[i * 3]     = c.r;
      colors[i * 3 + 1] = c.g;
      colors[i * 3 + 2] = c.b;
    }
    return { positions, colors };
  }, []);

  useFrame(({ clock }) => {
    if (ref.current) ref.current.rotation.z = clock.elapsedTime * 0.055;
  });

  return (
    <points ref={ref}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
        <bufferAttribute attach="attributes-color" args={[colors, 3]} />
      </bufferGeometry>
      <pointsMaterial
        size={0.03} vertexColors transparent opacity={0.6}
        sizeAttenuation depthWrite={false} blending={THREE.AdditiveBlending}
      />
    </points>
  );
}

// ─── Portal core (at the end) ──────────────────────────────────────────────────

function PortalCore() {
  const ref = useRef<THREE.Mesh>(null);
  useFrame(({ clock }) => {
    if (!ref.current) return;
    const mat = ref.current.material as THREE.MeshStandardMaterial;
    mat.emissiveIntensity = 3 + Math.sin(clock.elapsedTime * 1.4) * 0.9;
    ref.current.scale.setScalar(1 + Math.sin(clock.elapsedTime * 0.7) * 0.05);
  });
  return (
    <mesh ref={ref} position={[0, 0, -120]}>
      <sphereGeometry args={[2.2, 32, 32]} />
      <meshStandardMaterial
        color="#ff8d2b" emissive="#ff8d2b" emissiveIntensity={3}
        transparent opacity={0.95}
      />
    </mesh>
  );
}

// ─── Section gateway: a dramatic ring cluster the camera flies through ─────────

function SectionGateway({
  z, primary, accent,
}: {
  z: number; primary: string; accent: string;
}) {
  const outerRef = useRef<THREE.Mesh>(null);
  const innerRef = useRef<THREE.Mesh>(null);
  const midRef   = useRef<THREE.Mesh>(null);

  useFrame(({ clock }) => {
    const t = clock.elapsedTime;
    if (outerRef.current) outerRef.current.rotation.z =  t * 0.05;
    if (innerRef.current) innerRef.current.rotation.z = -t * 0.09;
    if (midRef.current)   midRef.current.rotation.z   =  t * 0.03;
  });

  return (
    <group position={[0, 0, z]}>
      {/* outer glow ring */}
      <mesh ref={outerRef}>
        <torusGeometry args={[5.2, 0.06, 8, 128]} />
        <meshStandardMaterial
          color={primary} emissive={primary} emissiveIntensity={5}
          transparent opacity={0.9} depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </mesh>
      {/* mid ring */}
      <mesh ref={midRef}>
        <torusGeometry args={[3.8, 0.04, 6, 100]} />
        <meshStandardMaterial
          color={accent} emissive={accent} emissiveIntensity={4}
          transparent opacity={0.65} depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </mesh>
      {/* inner ring */}
      <mesh ref={innerRef}>
        <torusGeometry args={[2.4, 0.03, 6, 80]} />
        <meshStandardMaterial
          color={primary} emissive={primary} emissiveIntensity={3}
          transparent opacity={0.45} depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </mesh>
    </group>
  );
}

// ─── NOSOTROS zone: orbiting network nodes ─────────────────────────────────────

function NosotrosElements() {
  const groupRef = useRef<THREE.Group>(null);

  useFrame(({ clock }) => {
    if (groupRef.current) {
      groupRef.current.rotation.y = clock.elapsedTime * 0.12;
      groupRef.current.rotation.z = clock.elapsedTime * 0.04;
    }
  });

  const nodes = useMemo(() =>
    Array.from({ length: 8 }, (_, i) => {
      const angle = (i / 8) * Math.PI * 2;
      const r = 3.2;
      return {
        pos: [Math.cos(angle) * r, Math.sin(angle) * r, (i % 3) * 0.8 - 0.8] as [number, number, number],
      };
    }), []);

  return (
    <group ref={groupRef} position={[0, 0, -36]}>
      {nodes.map(({ pos }, i) => (
        <mesh key={i} position={pos}>
          <sphereGeometry args={[0.09, 10, 10]} />
          <meshStandardMaterial
            color="#3d7fff" emissive="#3d7fff" emissiveIntensity={6}
            transparent opacity={0.9} depthWrite={false}
            blending={THREE.AdditiveBlending}
          />
        </mesh>
      ))}
      {/* central node */}
      <mesh>
        <sphereGeometry args={[0.18, 16, 16]} />
        <meshStandardMaterial
          color="#0546f2" emissive="#0546f2" emissiveIntensity={5}
          transparent opacity={0.95} depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </mesh>
    </group>
  );
}

// ─── SERVICIOS zone: 7 service spheres in a spiral ────────────────────────────

function ServiciosElements() {
  const groupRef = useRef<THREE.Group>(null);

  useFrame(({ clock }) => {
    if (groupRef.current) {
      groupRef.current.rotation.y = clock.elapsedTime * 0.09;
      groupRef.current.rotation.z = clock.elapsedTime * 0.035;
    }
  });

  const orbs = useMemo(() =>
    Array.from({ length: 7 }, (_, i) => {
      const angle = (i / 7) * Math.PI * 2;
      const r = 2.8;
      return {
        pos: [
          Math.cos(angle) * r,
          Math.sin(angle) * r,
          (i - 3) * 0.55,
        ] as [number, number, number],
        scale: 0.08 + (i % 3) * 0.04,
      };
    }), []);

  return (
    <group ref={groupRef} position={[0, 0, -60]}>
      {orbs.map(({ pos, scale }, i) => (
        <mesh key={i} position={pos}>
          <sphereGeometry args={[scale, 12, 12]} />
          <meshStandardMaterial
            color="#ff8d2b" emissive="#ff8d2b" emissiveIntensity={5}
            transparent opacity={0.9} depthWrite={false}
            blending={THREE.AdditiveBlending}
          />
        </mesh>
      ))}
    </group>
  );
}

// ─── MARCAS zone: two orbiting orbs (the 2 submarcas) ────────────────────────

function MarcasElements() {
  const orb1Ref = useRef<THREE.Mesh>(null);
  const orb2Ref = useRef<THREE.Mesh>(null);

  useFrame(({ clock }) => {
    const t = clock.elapsedTime * 0.4;
    const r = 2.6;
    if (orb1Ref.current) {
      orb1Ref.current.position.x = Math.cos(t) * r;
      orb1Ref.current.position.y = Math.sin(t) * r;
      const m = orb1Ref.current.material as THREE.MeshStandardMaterial;
      m.emissiveIntensity = 4 + Math.sin(clock.elapsedTime * 1.5) * 1.2;
    }
    if (orb2Ref.current) {
      orb2Ref.current.position.x = Math.cos(t + Math.PI) * r;
      orb2Ref.current.position.y = Math.sin(t + Math.PI) * r;
      const m = orb2Ref.current.material as THREE.MeshStandardMaterial;
      m.emissiveIntensity = 4 + Math.sin(clock.elapsedTime * 1.5 + Math.PI) * 1.2;
    }
  });

  return (
    <group position={[0, 0, -84]}>
      <mesh ref={orb1Ref}>
        <sphereGeometry args={[0.45, 20, 20]} />
        <meshStandardMaterial
          color="#ff8d2b" emissive="#ff8d2b" emissiveIntensity={4}
          transparent opacity={0.95}
        />
      </mesh>
      <mesh ref={orb2Ref}>
        <sphereGeometry args={[0.45, 20, 20]} />
        <meshStandardMaterial
          color="#0546f2" emissive="#0546f2" emissiveIntensity={4}
          transparent opacity={0.95}
        />
      </mesh>
      {/* shared aura */}
      <mesh>
        <sphereGeometry args={[0.2, 16, 16]} />
        <meshStandardMaterial
          color="#ffffff" emissive="#ffffff" emissiveIntensity={2}
          transparent opacity={0.5} depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </mesh>
    </group>
  );
}

// ─── Main tunnel ──────────────────────────────────────────────────────────────

const RING_COUNT = 24;

export default function PortalTunnel() {
  const rings = useMemo(
    () =>
      Array.from({ length: RING_COUNT }, (_, i) => {
        const t = i / (RING_COUNT - 1);
        return {
          z: -(i + 1) * 5.5,
          radius: 2.6 + i * 0.07,
          rotSpeed: (0.003 + i * 0.0002) * (i % 2 === 0 ? 1 : -1.3),
          color: t < 0.35 ? "#ff8d2b" : t < 0.65 ? "#0546f2" : "#152d80",
          opacity: Math.max(0.07, 0.9 - t * 0.6),
        };
      }),
    []
  );

  return (
    <>
      {/* Base tunnel rings */}
      {rings.map((r, i) => (
        <GlowRing key={i} {...r} />
      ))}

      <VortexParticles />

      {/* Section gateways — dramatic portals the camera flies through */}
      <SectionGateway z={-22} primary="#0546f2" accent="#3d7fff" />   {/* → Nosotros */}
      <SectionGateway z={-46} primary="#7c3aed" accent="#a855f7" />   {/* → Servicios */}
      <SectionGateway z={-70} primary="#ff8d2b" accent="#ffb347" />   {/* → Marcas */}

      {/* Section-specific floating elements */}
      <NosotrosElements />
      <ServiciosElements />
      <MarcasElements />

      <PortalCore />
    </>
  );
}
